\title{The Abundancy Index Framework for Perfect Numbers:\\
Structure of Even Perfects and the Deficiency of Prime Powers}
\author{Aristotle}
\date{June 27, 2026}

\begin{document}
\begin{abstract}
We develop a self-contained framework for the structural study of perfect numbers
organized around a single rational invariant, the \emph{abundancy index}
$\A(n)=\sigma(n)/n$, where $\sigma$ is the sum-of-divisors function. We show that
this invariant sorts the positive integers into the classical
perfect/deficient/abundant trichotomy and that perfection is equivalent to the
identity $\A(n)=2$. We prove that $\A$ is multiplicative on coprime arguments,
compute it explicitly on primes and prime powers, and establish that every prime
power is strictly deficient. From this we derive the first genuine structure
theorem: no perfect number is a prime power. We give the abundancy-theoretic
derivation of the Euclid--Euler classification of even perfect numbers,
$n=2^{p-1}(2^p-1)$ with $2^p-1$ prime, and explain how the same deficiency
estimate, iterated, drives Nielsen's lower bound that an odd perfect number must
have at least $101$ distinct prime factors. We close with a reciprocal-sum
identity for perfect numbers and a list of falsifiable conjectures. All central
results have been formally verified.
\end{abstract}

\maketitle

\section{Introduction}
A positive integer $n$ is \emph{perfect} if it equals the sum of its proper
divisors. The smallest examples---$6,28,496,8128$---were studied in antiquity.
Two structural questions remain open: whether there are infinitely many (even)
perfect numbers, and whether any \emph{odd} perfect number exists.

Writing $\sigma(n)$ for the sum of all positive divisors of $n$ (including $n$),
the \emph{abundancy index} is the rational number
\[
\A(n)=\frac{\sigma(n)}{n}.
\]
We assemble, from first principles and with formally verified proofs, the core of
the abundancy framework: the equivalence between perfection and $\A(n)=2$; the
multiplicativity of $\A$ on coprime arguments; the exact value of $\A$ on prime
powers; the uniform strict deficiency of prime powers; and the resulting
impossibility of a prime-power perfect number. We then place the Euclid--Euler
theorem and the Nielsen bound within this unified picture.

The conceptual narrative is that \emph{perfection is a balancing act}: the atoms
of multiplication---prime powers---are all strictly deficient ($\A<2$), and the
value $2$ can only be reached by multiplying several deficient atoms together
until their (multiplicative) abundancies land exactly on $2$.

\section{Definitions and conventions}
Throughout, $p$ denotes a prime and $\sigma=\sigma_1$ is the sum-of-divisors
function $\sigma(n)=\sum_{d\divides n}d$. All abundancy statements are made for
$n>0$; the value $\A(0)=\sigma(0)/0$ is undefined and excluded.

\begin{definition}[Abundancy index]
For $n>0$, $\A(n)=\sigma(n)/n\in\mathbb{Q}$.
\end{definition}
\begin{definition}[Deficient]
$n>0$ is \emph{deficient} if $\A(n)<2$.
\end{definition}
\begin{definition}[Abundant]
$n>0$ is \emph{abundant} if $\A(n)>2$.
\end{definition}
\begin{definition}[Perfect]
$n>0$ is \emph{perfect} if the sum of its proper divisors equals $n$; equivalently
$\sigma(n)=2n$.
\end{definition}

\section{Perfection as an abundancy identity}
\begin{lemma}[Reconstruction of $\sigma$]
For $n>0$, $\sigma(n)=\A(n)\cdot n$.
\end{lemma}
\begin{proof}
By definition $\A(n)=\sigma(n)/n$, and since $n>0$, multiplying back gives
$\frac{\sigma(n)}{n}\cdot n=\sigma(n)$.
\end{proof}

\begin{theorem}[Perfection $\Leftrightarrow$ abundancy two]
For $n>0$, $\A(n)=2 \iff n$ is perfect.
\end{theorem}
\begin{proof}
Since $n>0$, clearing the denominator gives
$\A(n)=2 \iff \sigma(n)/n=2 \iff \sigma(n)=2n$, which is exactly perfection.
\end{proof}

\section{Multiplicativity}
\begin{theorem}[Multiplicativity on coprime arguments]
If $\gcd(m,n)=1$ then $\A(mn)=\A(m)\,\A(n)$.
\end{theorem}
\begin{proof}
By multiplicativity of $\sigma$, $\sigma(mn)=\sigma(m)\sigma(n)$, so
\[
\A(mn)=\frac{\sigma(mn)}{mn}=\frac{\sigma(m)\sigma(n)}{m\,n}
=\frac{\sigma(m)}{m}\cdot\frac{\sigma(n)}{n}=\A(m)\,\A(n). \qedhere
\]
\end{proof}
Consequently, for $n=\prod_i p_i^{a_i}$ we have $\A(n)=\prod_i \A(p_i^{a_i})$: the
global invariant is the product of local invariants.

\section{Abundancy of primes and prime powers}
\begin{lemma}[Primes]
For a prime $p$, $\A(p)=\frac{p+1}{p}=1+\frac1p$.
\end{lemma}
\begin{proof}
The divisors of $p$ are $1,p$, so $\sigma(p)=p+1$; divide by $p$.
\end{proof}

\begin{lemma}[Prime powers]
For a prime $p$ and $k\ge1$,
\[
\sigma(p^k)=\frac{p^{k+1}-1}{p-1},\qquad
\A(p^k)=\sum_{i=0}^{k}p^{-i}=1+\tfrac1p+\cdots+\tfrac1{p^k}.
\]
\end{lemma}
\begin{proof}
The divisors are $1,p,\dots,p^k$, a geometric series summing to
$\frac{p^{k+1}-1}{p-1}$. Dividing by $p^k$ and reindexing gives the reciprocal sum.
\end{proof}

\begin{theorem}[Primes are deficient]
Every prime $p$ satisfies $\A(p)<2$.
\end{theorem}
\begin{proof}
$\frac{p+1}{p}<2 \iff p+1<2p \iff 1<p$, true for every prime.
\end{proof}

\begin{theorem}[Prime powers are deficient]
For every prime $p$ and $k\ge1$, $\A(p^k)<2$.
\end{theorem}
\begin{proof}
Multiplying by the positive quantity $p^k(p-1)$, the inequality $\A(p^k)<2$ is
equivalent to
\[
p^{k+1}-1<2p^k(p-1)\iff 0<p^k(p-2)+1.
\]
For $p=2$ the right side is $1>0$; for $p\ge3$, $p^k(p-2)\ge1>0$. Hence $\A(p^k)<2$.
\end{proof}

\section{First structure theorem: no perfect prime power}
\begin{theorem}[No perfect number is a prime power]
If $n$ is perfect, then $n\neq p^k$ for any prime $p$ and $k\ge1$.
\end{theorem}
\begin{proof}
If $n=p^k$ were perfect then $\A(n)=2$, contradicting $\A(p^k)<2$.
\end{proof}
\begin{corollary}
Every perfect number has at least two distinct prime factors.
\end{corollary}
\begin{proof}
A number with at most one distinct prime factor is $1$ (with $\A=1$) or a prime
power (excluded above).
\end{proof}

\section{A reciprocal-sum identity}
\begin{theorem}[Reciprocals of divisors]
For $n>0$, $\sum_{d\divides n}\frac1d=\A(n)$; in particular a perfect number has
$\sum_{d\divides n}\frac1d=2$.
\end{theorem}
\begin{proof}
The map $d\mapsto n/d$ is an involution on divisors, so
$\sum_{d\divides n}\frac1d=\frac1n\sum_{d\divides n}d=\frac{\sigma(n)}{n}=\A(n)$.
\end{proof}
For $n=6$: $1+\tfrac12+\tfrac13+\tfrac16=2$.

\section{The Euclid--Euler theorem through abundancy}
A \emph{Mersenne prime} is a prime $M_p=2^p-1$ (forcing $p$ prime).
\begin{theorem}[Euclid--Euler]
An even $n>0$ is perfect iff $n=2^{p-1}(2^p-1)$ with $2^p-1$ prime.
\end{theorem}
\begin{proof}[Sketch]
\emph{Sufficiency.} With $q=2^p-1$ prime and $n=2^{p-1}q$, coprimality gives
$\A(n)=\A(2^{p-1})\A(q)=\frac{2^p-1}{2^{p-1}}\cdot\frac{2^p}{2^p-1}
=\frac{2^p}{2^{p-1}}=2$, so $n$ is perfect.
\emph{Necessity.} Write $n=2^k m$ with $m$ odd, $k\ge1$. Then $\sigma(2^k)\sigma(m)=2^{k+1}m$,
i.e. $(2^{k+1}-1)\sigma(m)=2^{k+1}m$. As $2^{k+1}-1$ is odd and divides $2^{k+1}m$,
it divides $m$; writing $m=(2^{k+1}-1)c$ gives $\sigma(m)=m+c$, forcing $c=1$ and
$m=2^{k+1}-1$ prime. Set $p=k+1$.
\end{proof}

\section{Odd perfect numbers and Nielsen's bound}
For odd $n$, each local factor obeys $\A(p^a)<\frac{p}{p-1}$, so by
multiplicativity $\A(n)<\prod_{p\divides n}\frac{p}{p-1}$. Perfection forces
\[
\prod_{p\divides n}\frac{p}{p-1}>2.
\]
Since these partial products grow only like $\log x$ (Mertens), many distinct odd
primes are required.
\begin{theorem}[Nielsen, 2015]
An odd perfect number, if one exists, has at least $101$ distinct prime factors.
\end{theorem}
The conceptual core is the strict deficiency of prime powers, iterated and
sharpened.

\section{Algorithms}
\textbf{Algorithm A (Abundancy classification).} Compute $\sigma(n)$ by divisor
pairing $d\leftrightarrow n/d$ in $O(\sqrt n)$, form $\A(n)=\sigma(n)/n$ exactly,
compare with $2$.\\
\textbf{Algorithm B (Euclid--Euler generator).} For prime $p$, test primality of
$M_p=2^p-1$ (Lucas--Lehmer); when prime, emit $2^{p-1}M_p$. This enumerates all
even perfects.\\
\textbf{Algorithm C (Local-factor product).} Factor $n=\prod p_i^{a_i}$, compute
each $\A(p_i^{a_i})=(p_i^{a_i+1}-1)/(p_i^{a_i}(p_i-1))$, multiply.

\section{Future directions}
\begin{conjecture}[Toward Nielsen]
A perfect number with at most $k$ distinct prime factors satisfies
$\prod_{p\divides n}\frac{p}{p-1}\ge2$; logarithmic growth of this product over
small odd primes forces an odd perfect number to have many prime factors.
\end{conjecture}
\begin{conjecture}[Euler's form]
An odd perfect $n$ has the form $p^a m^2$ with $p$ prime,
$p\equiv a\equiv1\pmod4$, $p\nmid m$.
\end{conjecture}
\begin{conjecture}
No perfect number is a perfect square (parity of $\sigma$).
\end{conjecture}
\begin{conjecture}[Odd cubes]
Every even perfect $n>6$, with $n=2^{p-1}(2^p-1)$, equals
$\sum_{j=1}^{t}(2j-1)^3=t^2(2t^2-1)$ for $t=2^{(p-1)/2}$.
\end{conjecture}
\begin{conjecture}[Triangular locus]
A triangular number $T_m=m(m+1)/2$ is perfect iff $m=2^p-1$ is a Mersenne prime.
\end{conjecture}

\section{Conclusion}
A single rational invariant, $\A(n)=\sigma(n)/n$, organizes perfect-number theory:
perfection is $\A(n)=2$; multiplicativity reduces $\A$ to prime-power values; those
values are uniformly $<2$. From this one deficiency fact follow the impossibility
of prime-power perfects, the Euclid--Euler classification, and the mechanism
behind Nielsen's $101$-prime bound.

\end{document}

