function ABUNDANCY(n):
    A <- Rational(1, 1)
    m <- n
    for prime p dividing m (in increasing order):
        a <- 0
        while m mod p == 0:
            m <- m / p; a <- a + 1
        local <- Rational(p^(a+1) - 1, p^a * (p - 1))
        A <- A * local
    return A
